:root {
  --acid: #c9ff2f;
  --acid-dim: #9ecb24;
  --orange: #ff5b2b;
  --bg: #070908;
  --ink: #eff2e8;
  --muted: #89938c;
  --dim: #59635d;
  --line: rgba(241, 246, 236, 0.12);
  --line-strong: rgba(241, 246, 236, 0.22);
  --panel: rgba(9, 12, 11, 0.81);
  --panel-solid: #0c100e;
  --glass: rgba(255, 255, 255, 0.035);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; }
html { background: var(--bg); }
body {
  overflow: hidden;
  font-family: 'Inter', system-ui, sans-serif;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  touch-action: none;
}
button, input { font: inherit; }
button { color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible, input:focus-visible { outline: 2px solid var(--acid); outline-offset: 2px; }
::selection { background: var(--acid); color: #080a09; }

#gl {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  display: block;
  z-index: 0;
  touch-action: none;
}

.grain {
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: 0.065;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}
.vignette {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: radial-gradient(ellipse at 53% 45%, transparent 35%, rgba(0,0,0,.44) 100%);
}

.eyebrow {
  display: block;
  font-size: 9px;
  line-height: 1.2;
  font-weight: 500;
  letter-spacing: .19em;
  color: var(--muted);
  text-transform: uppercase;
}
.eyebrow i { font-style: normal; color: var(--dim); }

/* ---------- Loading ---------- */
.loading {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: #070908;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transition: opacity .55s ease, visibility .55s ease;
}
.loading.is-done { opacity: 0; visibility: hidden; pointer-events: none; }
.loading-mark {
  width: 56px;
  height: 66px;
  position: relative;
  margin-bottom: 26px;
  transform: skewX(-14deg);
}
.loading-mark::before, .loading-mark::after {
  content: '';
  position: absolute;
  width: 16px;
  height: 66px;
  background: var(--acid);
  left: 8px;
}
.loading-mark::after { left: 31px; background: var(--ink); opacity: .9; }
.loading-word {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 58px;
  font-weight: 900;
  letter-spacing: .18em;
  line-height: 1;
  text-indent: .18em;
}
.loading-sub {
  margin-top: 11px;
  font-size: 9px;
  letter-spacing: .32em;
  color: var(--muted);
}
.loading-track {
  width: min(300px, 64vw);
  height: 1px;
  background: rgba(255,255,255,.12);
  margin-top: 40px;
  position: relative;
  overflow: hidden;
}
.loading-track i {
  position: absolute;
  inset: 0 auto 0 0;
  width: 0%;
  background: var(--acid);
  transition: width .3s ease;
  box-shadow: 0 0 10px var(--acid);
}
.loading-meta {
  width: min(300px, 64vw);
  margin-top: 12px;
  display: flex;
  justify-content: space-between;
  font-size: 8px;
  letter-spacing: .16em;
  color: var(--dim);
}

/* ---------- Showroom shell ---------- */
.showroom-ui {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  transition: opacity .4s ease, visibility .4s ease;
}
.showroom-ui.is-hidden { opacity: 0; visibility: hidden; }
.showroom-ui > * { pointer-events: auto; }

.topbar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: calc(78px + var(--safe-top));
  padding: var(--safe-top) 30px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  background: linear-gradient(to bottom, rgba(6,8,7,.88), rgba(6,8,7,0));
}
.brand { display: flex; align-items: center; gap: 13px; min-width: 200px; }
.brand-mark {
  width: 27px;
  height: 36px;
  position: relative;
  display: inline-block;
  transform: skewX(-14deg);
  flex: 0 0 auto;
}
.brand-mark i {
  position: absolute;
  top: 0;
  width: 7px;
  height: 100%;
  background: var(--acid);
  box-shadow: 0 0 22px rgba(201,255,47,.2);
}
.brand-mark i:first-child { left: 4px; }
.brand-mark i:last-child { left: 16px; background: var(--ink); opacity: .92; }
.brand-mark.small { width: 19px; height: 26px; }
.brand-mark.small i { width: 5px; }
.brand-mark.small i:first-child { left: 3px; }
.brand-mark.small i:last-child { left: 11px; }
.brand-copy { display: flex; flex-direction: column; gap: 3px; }
.brand-copy strong {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 20px;
  line-height: .9;
  letter-spacing: .14em;
  font-weight: 900;
}
.brand-copy span {
  font-size: 7.5px;
  letter-spacing: .22em;
  color: var(--muted);
}
.top-status {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 9px;
  font-weight: 500;
  letter-spacing: .16em;
  color: #c9d2ca;
}
.status-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 8px var(--acid);
  display: inline-block;
}
.status-dot.pulse { animation: dotPulse 2.2s infinite; }
@keyframes dotPulse { 0%,100% { opacity: 1; } 50% { opacity: .28; } }
.slash { color: var(--dim); }
.muted { color: var(--muted); }
.top-actions { display: flex; align-items: center; gap: 8px; }
.icon-button {
  height: 34px;
  padding: 0 12px;
  display: flex;
  align-items: center;
  gap: 9px;
  border: 1px solid var(--line);
  background: rgba(13,17,15,.5);
  backdrop-filter: blur(10px);
  font-size: 8px;
  letter-spacing: .14em;
  color: var(--muted);
  transition: border-color .2s, color .2s, background .2s;
}
.icon-button:hover { border-color: var(--line-strong); color: var(--ink); background: rgba(20,25,22,.7); }
.sound-bars { height: 11px; display: flex; align-items: flex-end; gap: 2px; }
.sound-bars i { width: 2px; background: var(--acid); height: 40%; transition: height .2s; }
.sound-bars i:nth-child(2) { height: 100%; }
.sound-bars i:nth-child(3) { height: 65%; }
.sound-bars i:nth-child(4) { height: 82%; }
.icon-button.is-muted .sound-bars i { height: 18% !important; background: var(--dim); }
.icon-button.is-muted #soundLabel { color: var(--dim); }
.help-glyph {
  width: 13px; height: 13px; display: grid; place-items: center;
  border: 1px solid var(--muted); border-radius: 50%; font-size: 7px;
}

.stage-label {
  position: absolute;
  top: 126px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  writing-mode: vertical-rl;
  font-size: 7px;
  letter-spacing: .24em;
  color: rgba(210,220,211,.32);
  pointer-events: none;
}
.stage-label-left { left: 8px; }
.stage-label-right { right: 8px; align-items: flex-end; }

/* ---------- Build panel ---------- */
.build-panel {
  position: absolute;
  left: 30px;
  top: calc(92px + var(--safe-top));
  bottom: 84px;
  width: 378px;
  max-height: 720px;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  background: var(--panel);
  backdrop-filter: blur(18px) saturate(120%);
  box-shadow: 0 30px 80px rgba(0,0,0,.34);
  overflow: hidden;
}
.build-panel::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 34px; height: 2px;
  background: var(--acid);
}
.panel-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 20px 20px 15px;
}
.panel-heading h1 {
  font-family: 'Barlow Condensed', sans-serif;
  font-weight: 900;
  font-size: 31px;
  line-height: .95;
  letter-spacing: .04em;
  margin: 7px 0 0;
}
.panel-index {
  display: flex;
  align-items: baseline;
  gap: 3px;
  font-family: 'Barlow Condensed', sans-serif;
  font-weight: 700;
  color: var(--acid);
  font-size: 19px;
}
.panel-index small { font-size: 9px; color: var(--dim); letter-spacing: .06em; }

.tabs {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  margin: 0 14px;
}
.tab {
  position: relative;
  padding: 10px 0 11px;
  text-align: center;
  color: var(--muted);
  transition: color .2s, background .2s;
}
.tab span {
  display: block;
  font-family: 'Barlow Condensed', sans-serif;
  font-weight: 600;
  font-size: 9.5px;
  letter-spacing: .08em;
  line-height: 1.2;
}
.tab small {
  display: block;
  font-size: 6.5px;
  letter-spacing: .1em;
  color: var(--dim);
  margin-bottom: 4px;
}
.tab:hover { color: var(--ink); background: rgba(255,255,255,.03); }
.tab.is-active { color: var(--acid); }
.tab.is-active::after {
  content: '';
  position: absolute;
  bottom: -1px; left: 18%; right: 18%;
  height: 2px;
  background: var(--acid);
  box-shadow: 0 0 8px rgba(201,255,47,.5);
}

.build-content {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 18px 20px 20px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,.16) transparent;
}
.build-content::-webkit-scrollbar { width: 4px; }
.build-content::-webkit-scrollbar-thumb { background: rgba(255,255,255,.16); }
.build-content::-webkit-scrollbar-track { background: transparent; }
.section-label { margin: 0 0 13px; }
.section-label:not(:first-child) { margin-top: 23px; }
.section-label h3 {
  margin: 0 0 5px;
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .14em;
  color: #d7ded5;
}
.section-label p { margin: 0; font-size: 9px; line-height: 1.55; color: var(--dim); max-width: 290px; }

.option-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 5px; }
.option-grid.three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.option {
  min-height: 56px;
  padding: 9px 10px;
  text-align: left;
  border: 1px solid var(--line);
  background: rgba(255,255,255,.018);
  transition: border-color .18s, background .18s, transform .18s;
  overflow: hidden;
}
.option:hover { border-color: var(--line-strong); background: rgba(255,255,255,.045); }
.option.is-active {
  border-color: rgba(201,255,47,.62);
  background: linear-gradient(135deg, rgba(201,255,47,.1), rgba(201,255,47,.02));
  box-shadow: inset 0 0 0 1px rgba(201,255,47,.08);
}
.option .tag {
  display: block;
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: .035em;
  line-height: 1.05;
  color: var(--ink);
}
.option.is-active .tag { color: var(--acid); }
.option small { display: block; margin-top: 4px; font-size: 7.5px; letter-spacing: .09em; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.option .badge {
  float: right;
  font-size: 7px;
  letter-spacing: .08em;
  color: var(--dim);
}
.option .meta { display: block; margin-top: 4px; font-size: 7.5px; color: var(--dim); letter-spacing: .06em; }

.slider-row { margin-top: 16px; }
.slider-row:first-child { margin-top: 0; }
.slider-meta { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
.slider-meta label { font-size: 8.5px; font-weight: 500; letter-spacing: .14em; color: #b8c1b8; }
.slider-meta output {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: .04em;
  color: var(--acid);
  white-space: nowrap;
}
.slider-meta output span { font-family: 'Inter', sans-serif; font-size: 7px; color: var(--dim); margin-left: 3px; letter-spacing: .08em; }
input[type='range'] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 2px;
  background: linear-gradient(to right, var(--acid) 0%, var(--acid) var(--fill, 50%), rgba(255,255,255,.13) var(--fill, 50%), rgba(255,255,255,.13) 100%);
  outline: none;
  cursor: pointer;
  margin: 0;
}
input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 11px;
  height: 11px;
  background: var(--acid);
  border: 2px solid #0b0e0c;
  border-radius: 50%;
  box-shadow: 0 0 0 1px var(--acid), 0 0 10px rgba(201,255,47,.32);
}
input[type='range']::-moz-range-thumb {
  width: 9px; height: 9px; background: var(--acid); border: 2px solid #0b0e0c; border-radius: 50%;
}
.slider-scale { display: flex; justify-content: space-between; margin-top: 7px; font-size: 6.5px; letter-spacing: .12em; color: var(--dim); }

.swatch-grid { display: grid; grid-template-columns: repeat(8, 1fr); gap: 8px; }
.swatch {
  aspect-ratio: 1;
  border-radius: 50%;
  position: relative;
  border: 1px solid rgba(255,255,255,.18);
  box-shadow: inset 0 1px 4px rgba(255,255,255,.18), 0 2px 4px rgba(0,0,0,.3);
  transition: transform .15s;
}
.swatch:hover { transform: scale(1.12); }
.swatch.is-active { box-shadow: 0 0 0 2px #0b0e0c, 0 0 0 3px var(--acid), inset 0 1px 4px rgba(255,255,255,.3); }
.swatch.custom { display: grid; place-items: center; background: #1a1f1c; color: var(--muted); font-size: 11px; border-style: dashed; }
.swatch.custom input { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer; }

.finish-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 5px; }
.finish {
  padding: 8px 6px;
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 10px;
  letter-spacing: .08em;
  border: 1px solid var(--line);
  color: var(--muted);
  text-align: center;
}
.finish.is-active { border-color: rgba(201,255,47,.55); color: var(--acid); background: rgba(201,255,47,.06); }

.toggle-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 11px 0;
  border-top: 1px solid var(--line);
}
.toggle-row label { font-size: 9px; letter-spacing: .11em; color: #b8c1b8; }
.toggle {
  width: 34px; height: 18px; border: 1px solid var(--line-strong); border-radius: 20px;
  position: relative; background: rgba(255,255,255,.04);
}
.toggle::after {
  content: ''; position: absolute; width: 12px; height: 12px; top: 2px; left: 2px;
  border-radius: 50%; background: var(--dim); transition: transform .2s, background .2s;
}
.toggle.is-on { border-color: var(--acid); background: rgba(201,255,47,.1); }
.toggle.is-on::after { transform: translateX(16px); background: var(--acid); }

.audio-visual {
  height: 54px;
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  background: rgba(0,0,0,.18);
  margin-bottom: 14px;
  overflow: hidden;
}
.audio-visual i {
  flex: 1; height: 20%; background: var(--acid); opacity: .55;
  min-width: 1px; transition: height .14s linear;
}
.rev-button {
  width: 100%; display: flex; align-items: center; justify-content: space-between;
  padding: 11px 12px; margin: 14px 0 0;
  border: 1px solid rgba(201,255,47,.45);
  background: rgba(201,255,47,.07);
  color: var(--acid); font-size: 9px; letter-spacing: .14em;
}
.rev-button:hover { background: rgba(201,255,47,.13); }
.rev-button b { font-family: 'Barlow Condensed', sans-serif; font-size: 15px; }

.note-box {
  margin-top: 15px;
  padding: 10px 11px;
  border-left: 2px solid var(--acid);
  background: rgba(201,255,47,.04);
  font-size: 8.5px;
  line-height: 1.55;
  color: var(--muted);
}
.note-box b { color: #cfd8cf; }

.panel-foot {
  display: flex;
  gap: 6px;
  padding: 11px 20px calc(11px + var(--safe-bottom));
  border-top: 1px solid var(--line);
}
.ghost-button {
  flex: 1;
  height: 33px;
  border: 1px solid var(--line);
  font-size: 8px;
  letter-spacing: .12em;
  color: #b6beb5;
  display: flex; align-items: center; justify-content: center; gap: 8px;
  transition: border-color .2s, color .2s, background .2s;
}
.ghost-button:hover { border-color: var(--line-strong); color: var(--ink); background: rgba(255,255,255,.03); }
.ghost-button.subtle { flex: 0 0 82px; color: var(--dim); }
.ghost-button kbd { font-family: 'Inter', sans-serif; font-size: 6.5px; color: var(--dim); padding: 2px 4px; border: 1px solid var(--line); margin-left: 2px; }
.dice { color: var(--acid); font-size: 12px; line-height: 1; }

/* ---------- Telemetry panel ---------- */
.spec-panel {
  position: absolute;
  right: 30px;
  top: calc(92px + var(--safe-top));
  width: 304px;
  max-height: 720px;
  padding: 18px 19px 16px;
  border: 1px solid var(--line);
  background: var(--panel);
  backdrop-filter: blur(18px) saturate(120%);
  box-shadow: 0 30px 80px rgba(0,0,0,.34);
  display: flex;
  flex-direction: column;
}
.spec-panel::before {
  content: '';
  position: absolute; right: 19px; top: 0;
  width: 2px; height: 24px; background: var(--acid);
}
.spec-top { display: flex; justify-content: space-between; align-items: center; }
.live-tag { font-size: 7px; letter-spacing: .14em; color: var(--acid); display: flex; align-items: center; gap: 5px; }
.live-tag i { width: 4px; height: 4px; border-radius: 50%; background: var(--acid); box-shadow: 0 0 8px var(--acid); animation: dotPulse 2s infinite; }
.power-block { margin-top: 17px; padding-bottom: 16px; border-bottom: 1px solid var(--line); }
.power-value { display: flex; align-items: flex-start; gap: 5px; }
.power-value span {
  font-family: 'Barlow Condensed', sans-serif;
  font-weight: 900;
  font-size: 66px;
  line-height: .82;
  letter-spacing: -.02em;
  color: var(--ink);
}
.power-value small { font-family: 'Barlow Condensed', sans-serif; font-size: 17px; font-weight: 700; color: var(--acid); margin-top: 2px; letter-spacing: .05em; }
.power-caption { display: flex; justify-content: space-between; gap: 10px; margin-top: 8px; font-size: 7px; letter-spacing: .13em; color: var(--dim); }
.power-caption b { color: var(--muted); font-weight: 500; text-align: right; }
.quick-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); margin-top: 1px; }
.quick-stats > div { background: rgba(9,12,11,.88); padding: 11px 8px 10px; }
.quick-stats span { display: block; font-size: 6.5px; letter-spacing: .1em; color: var(--dim); margin-bottom: 5px; }
.quick-stats strong { font-family: 'Barlow Condensed', sans-serif; font-size: 19px; font-weight: 700; letter-spacing: .02em; line-height: 1; }
.quick-stats strong small { font-family: 'Inter', sans-serif; font-size: 6.5px; font-weight: 400; color: var(--dim); margin-left: 2px; letter-spacing: .02em; }
.metric-list { padding: 15px 0 12px; border-bottom: 1px solid var(--line); }
.metric { margin-top: 10px; }
.metric:first-child { margin-top: 0; }
.metric > div:first-child { display: flex; justify-content: space-between; margin-bottom: 5px; }
.metric span { font-size: 7px; letter-spacing: .14em; color: var(--muted); }
.metric b { font-family: 'Barlow Condensed', sans-serif; font-size: 11px; color: #c8d0c7; font-weight: 600; }
.meter { height: 2px; background: rgba(255,255,255,.1); overflow: hidden; }
.meter i { display: block; height: 100%; width: 50%; background: linear-gradient(to right, var(--acid-dim), var(--acid)); transition: width .4s cubic-bezier(.2,.8,.2,1); }
.spec-sheet { padding-top: 13px; }
.spec-sheet .eyebrow { margin-bottom: 8px; }
.spec-row { display: flex; justify-content: space-between; gap: 12px; padding: 4.5px 0; font-size: 7px; letter-spacing: .09em; }
.spec-row span { color: var(--dim); }
.spec-row b { color: #bdc6bd; font-weight: 500; text-align: right; }
.drive-button {
  margin-top: 16px;
  height: 62px;
  width: 100%;
  background: var(--acid);
  color: #080b08;
  display: flex;
  align-items: center;
  padding: 0 14px;
  gap: 12px;
  position: relative;
  transition: background .2s, transform .2s;
  box-shadow: 0 0 35px rgba(201,255,47,.12);
}
.drive-button:hover { background: #dcff5f; transform: translateY(-1px); }
.drive-num { font-family: 'Barlow Condensed', sans-serif; font-size: 13px; font-weight: 700; opacity: .45; align-self: flex-start; margin-top: 12px; }
.drive-copy { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; }
.drive-copy small { font-size: 6.5px; letter-spacing: .18em; font-weight: 600; opacity: .55; }
.drive-copy strong { font-family: 'Barlow Condensed', sans-serif; font-size: 21px; font-weight: 900; letter-spacing: .04em; line-height: 1; }
.drive-arrow { margin-left: auto; font-size: 22px; font-weight: 300; }
.drive-hint { margin-top: 10px; display: flex; align-items: center; justify-content: center; gap: 4px; font-size: 6.5px; letter-spacing: .1em; color: var(--dim); }
.drive-hint i { width: 14px; height: 1px; background: var(--line); margin: 0 5px; }
.key { display: inline-grid; place-items: center; width: 14px; height: 14px; border: 1px solid var(--line-strong); color: var(--muted); font-size: 6.5px; }

/* ---------- Footer ---------- */
.garage-footer {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: calc(64px + var(--safe-bottom));
  padding: 0 30px var(--safe-bottom);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  background: linear-gradient(to top, rgba(6,8,7,.9), rgba(6,8,7,.3), transparent);
  border-top: 1px solid rgba(255,255,255,.07);
  gap: 20px;
}
.build-id { display: flex; flex-direction: column; gap: 3px; }
.build-id .eyebrow { font-size: 7px; }
.build-id input {
  width: 230px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  line-height: 1.1;
}
.build-id input:focus { outline: none; border-bottom: 1px solid var(--acid); }
.saved { font-size: 6.5px; letter-spacing: .12em; color: var(--dim); }
.saved.flash { color: var(--acid); }
.footer-center { display: flex; align-items: center; gap: 14px; font-size: 7px; letter-spacing: .12em; color: var(--dim); }
.footer-rule { width: 28px; height: 1px; background: var(--line); }
.coordinate { color: rgba(197,208,197,.42); }
.build-space { justify-self: end; text-align: right; display: flex; flex-direction: column; gap: 2px; }
.build-space strong { font-family: 'Barlow Condensed', sans-serif; font-size: 24px; font-weight: 700; letter-spacing: .03em; line-height: 1; color: var(--ink); }
.build-space .infinite { font-size: 6.5px; letter-spacing: .1em; color: var(--dim); }
.mobile-drive-wrap { display: none; }

/* ---------- HUD ---------- */
.hud {
  position: fixed;
  inset: 0;
  z-index: 11;
