function saveSoon() {
  clearTimeout(saveSoon.timer);
  saveSoon.timer = setTimeout(() => {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(build)); } catch {}
    const tag = $('#savedTag');
    tag.classList.add('flash');
    setTimeout(() => tag.classList.remove('flash'), 500);
  }, 280);
