function stepPhysics(dt) {
  if (!worldCar) return;
  const s = physics;
  const d = worldCar.dimensions;
  const st = worldCar.stats;
  readDrivingInput();

  s.throttle = damp(s.throttle, input.throttle, 9, dt);
  s.brake = damp(s.brake, input.brake, 14, dt);
  s.steer = damp(s.steer, input.steer, 10, dt);
