@media (hover: none) {
  .hud-help, .drive-hint { display: none; }
  /* Tablets in landscape keep the desktop HUD, but still need thumbs. */
  .touch-controls {
    display: flex;
    position: fixed;
    left: 0; right: 0; bottom: calc(14px + var(--safe-bottom));
    justify-content: space-between;
    align-items: flex-end;
    padding: 0 22px;
    pointer-events: none;
    z-index: 14;
  }
  .touch-controls button { pointer-events: auto; touch-action: none; user-select: none; }
  .touch-steer { display: flex; gap: 10px; }
  .touch-steer button, .touch-pedal, .touch-small {
    border: 1px solid rgba(255,255,255,.25);
    background: rgba(8,11,9,.55);
    backdrop-filter: blur(8px);
    color: var(--ink);
    font-family: 'Barlow Condensed', sans-serif;
    font-weight: 700;
    letter-spacing: .06em;
    display: grid; place-items: center;
    touch-action: none;
  }
  .touch-steer button { width: 68px; height: 68px; border-radius: 50%; font-size: 20px; }
  .touch-pedals { display: flex; align-items: flex-end; gap: 8px; }
  .touch-pedal { width: 64px; height: 84px; border-radius: 32px 32px 26px 26px; font-size: 10px; }
  .touch-pedal.gas { background: rgba(201,255,47,.2); border-color: rgba(201,255,47,.55); color: var(--acid); }
  .touch-small { width: 46px; height: 46px; border-radius: 50%; font-size: 7px; }
  .touch-small.nitro { color: #7ce7f4; border-color: rgba(66,245,255,.35); }
  .touch-controls button.is-down { background: rgba(201,255,47,.35); border-color: var(--acid); }
}
@media (hover: none) and (min-width: 821px) and (min-height: 621px) {
  .speed-cluster { bottom: calc(126px + var(--safe-bottom)); }
  .drift-status { bottom: calc(226px + var(--safe-bottom)); }
}

